<?php if ($canManage): ?><details class="card form-card" <?= $error && ($_POST['action'] ?? '')==='create' ? 'open' : '' ?>><summary>+ Créer un code promotionnel</summary><form method="post" action="marketing" class="form-grid"><input type="hidden" name="csrf" value="<?= e(csrf()) ?>"><input type="hidden" name="action" value="create"><label>Code *<input name="code" maxlength="40" pattern="[A-Za-z0-9_-]{3,40}" value="<?= e($_POST['code'] ?? '') ?>" placeholder="BIENVENUE10" required></label><label>Libellé *<input name="label" maxlength="120" value="<?= e($_POST['label'] ?? '') ?>" required></label><label>Réduction (%) *<input type="number" name="discount_percent" min="0.01" max="100" step="0.01" value="<?= e($_POST['discount_percent'] ?? '') ?>" required></label><label>Date de début *<input type="date" name="starts_on" value="<?= e($_POST['starts_on'] ?? date('Y-m-d')) ?>" required></label><label>Date de fin *<input type="date" name="ends_on" value="<?= e($_POST['ends_on'] ?? '') ?>" required></label><p class="form-hint">La promotion est utilisable sur un nouvel abonnement ou un renouvellement pendant sa période de validité. Un récapitulatif du prix est affiché avant confirmation.</p><div class="form-actions"><button class="primary">Créer la promotion</button></div></form></details><?php endif; ?>
<section class="card management-table"><div class="card-head"><div><h3>Codes promotionnels</h3><p><?= $total ?> code(s) · réductions sur les abonnements</p></div></div><div class="table-scroll"><table><thead><tr><th>CODE</th><th>OFFRE</th><th>RÉDUCTION</th><th>VALIDITÉ</th><th>STATUT</th><?php if ($canManage): ?><th>ACTION</th><?php endif; ?></tr></thead><tbody><?php foreach ($promotions as $promo): $status=!$promo['is_active'] ? 'Désactivée' : ($promo['starts_on']>date('Y-m-d') ? 'À venir' : ($promo['ends_on']<date('Y-m-d') ? 'Expirée' : 'En cours')); ?><tr><td><strong><?= e($promo['code']) ?></strong></td><td><?= e($promo['label']) ?></td><td><?= e(number_format((float)$promo['discount_percent'],2,',',' ')) ?> %</td><td><?= e(date('d/m/Y',strtotime($promo['starts_on']))) ?> – <?= e(date('d/m/Y',strtotime($promo['ends_on']))) ?></td><td><span class="status <?= $status!=='En cours' ? 'waiting-status' : '' ?>"><?= e($status) ?></span></td><?php if ($canManage): ?><td><form method="post" action="marketing"><input type="hidden" name="csrf" value="<?= e(csrf()) ?>"><input type="hidden" name="action" value="toggle"><input type="hidden" name="id" value="<?= (int)$promo['id'] ?>"><input type="hidden" name="active" value="<?= $promo['is_active'] ? '0' : '1' ?>"><button class="link-button"><?= $promo['is_active'] ? 'Désactiver' : 'Activer' ?></button></form></td><?php endif; ?></tr><?php endforeach; ?><?php if (!$promotions): ?><tr><td colspan="6" class="empty">Aucune promotion enregistrée.</td></tr><?php endif; ?></tbody></table></div><div class="pagination"><?php if ($pageNumber>1): ?><a href="marketing?p=<?= $pageNumber-1 ?>">← Précédent</a><?php endif; ?><span>Page <?= $pageNumber ?> / <?= max(1,(int)ceil($total/10)) ?></span><?php if ($pageNumber*10<$total): ?><a href="marketing?p=<?= $pageNumber+1 ?>">Suivant →</a><?php endif; ?></div></section>
<div class="marketing-grid"><section class="card management-table"><div class="card-head"><div><h3>Anniversaires du mois</h3><p>Membres actifs autorisés · jusqu’à 100 résultats</p></div><span class="stat-icon amber"><i data-lucide="cake"></i></span></div><div class="table-scroll"><table><thead><tr><th>MEMBRE</th><th>DATE</th><th>CONTACT</th></tr></thead><tbody><?php foreach ($birthdays as $m): $link=MarketingConsent::phone($m['phone'])!==null; ?><tr><td><?= e($m['first_name'].' '.$m['last_name']) ?></td><td><?= e(date('d/m',strtotime($m['birth_date']))) ?></td><td><?php if ($link): ?><a class="text-link" href="marketing_whatsapp?kind=birthday&amp;id=<?= (int)$m['id'] ?>" target="_blank" rel="noopener noreferrer">WhatsApp ↗</a><?php else: ?><span class="form-hint">Numéro indisponible</span><?php endif; ?></td></tr><?php endforeach; ?><?php if (!$birthdays): ?><tr><td colspan="3" class="empty">Aucun anniversaire ce mois-ci.</td></tr><?php endif; ?></tbody></table></div></section><section class="card management-table"><div class="card-head"><div><h3>Relances d’expiration</h3><p>Membres autorisés · expiration sous 7 jours · jusqu’à 100 résultats</p></div><span class="stat-icon mint"><i data-lucide="message-circle"></i></span></div><div class="table-scroll"><table><thead><tr><th>MEMBRE</th><th>EXPIRATION</th><th>CONTACT</th></tr></thead><tbody><?php foreach ($expiring as $m): $link=MarketingConsent::phone($m['phone'])!==null; ?><tr><td><?= e($m['first_name'].' '.$m['last_name']) ?></td><td><?= e(date('d/m/Y',strtotime($m['end_date']))) ?></td><td><?php if ($link): ?><a class="text-link" href="marketing_whatsapp?kind=expiry&amp;id=<?= (int)$m['subscription_id'] ?>" target="_blank" rel="noopener noreferrer">WhatsApp ↗</a><?php else: ?><span class="form-hint">Numéro indisponible</span><?php endif; ?></td></tr><?php endforeach; ?><?php if (!$expiring): ?><tr><td colspan="3" class="empty">Aucune échéance imminente.</td></tr><?php endif; ?></tbody></table></div></section></div>
